package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Grouped online catalogue restored in owned code; browsing never requests tiles. */
public final class MapCatalogActivity extends Activity {
 public static final String RESULT_ACTION="catalog_action";public static final int ACTION_SETTINGS=1,ACTION_EXPORT=2;
 private long project;private LinearLayout root,list;private ScrollView scroll;private TextView state;private SharedPreferences prefs;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Map<String,long[]> cache=new HashMap<>();private final Map<String,Bitmap> previews=new HashMap<>();private volatile boolean disposed;private int generation;private boolean loading=true;private int restoreY;
 protected void onCreate(Bundle saved){super.onCreate(saved);project=getIntent().getLongExtra("project",-1);prefs=getSharedPreferences("catalog-ui",0);restoreY=saved==null?0:saved.getInt("scroll",0);getWindow().setStatusBarColor(0xff172012);getWindow().setNavigationBarColor(0xff172012);build();scan();}
 private int dp(float value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
 private TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 private TextView icon(String text,String description,Runnable run){TextView v=label(text,25,Color.WHITE);v.setGravity(Gravity.CENTER);v.setContentDescription(description);v.setMinHeight(dp(48));v.setFocusable(true);v.setOnClickListener(w->run.run());return v;}
 private void build(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff202c19);setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);root.addView(header,new LinearLayout.LayoutParams(-1,dp(66)));header.addView(icon("☰","Меню онлайн-карт",()->menu()),new LinearLayout.LayoutParams(dp(52),-1));LinearLayout title=new LinearLayout(this);title.setOrientation(1);title.addView(label("Онлайн-карты",22,-1));title.addView(label("Установленные карты",16,0xffd0d6c9));header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView close=icon("×","Закрыть онлайн-карты",()->finish());close.setTextColor(0xffd27165);header.addView(close,new LinearLayout.LayoutParams(dp(44),-1));header.addView(icon("⋮","Действия каталога",()->menu()),new LinearLayout.LayoutParams(dp(44),-1));
  LinearLayout storage=new LinearLayout(this);storage.setGravity(Gravity.CENTER_VERTICAL);storage.setPadding(dp(24),dp(12),dp(16),dp(12));root.addView(storage,new LinearLayout.LayoutParams(-1,dp(58)));long total=getFilesDir().getTotalSpace(),free=getFilesDir().getUsableSpace(),used=Math.max(0,total-free);FrameLayout meter=new FrameLayout(this);meter.setBackgroundColor(0xffd0d6c9);storage.addView(meter,new LinearLayout.LayoutParams(0,dp(18),1));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress(total>0?(int)(used*1000.0/total):0);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff36c839));meter.addView(bar,new FrameLayout.LayoutParams(-1,-1));TextView amount=label(String.format(Locale.US,"%.1f / %.1f ГиБ",used/1073741824.0,total/1073741824.0),11,0xff172012);amount.setGravity(Gravity.CENTER);meter.addView(amount,new FrameLayout.LayoutParams(-1,-1));storage.addView(icon("⚙","Кеш и загрузка",()->returnAction(null,ACTION_SETTINGS)),new LinearLayout.LayoutParams(dp(48),dp(40)));
  state=label("Чтение локального кеша…",12,0xffd0d6c9);state.setPadding(dp(16),0,dp(16),dp(6));root.addView(state);scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);render();
 }
 private void render(){if(disposed)return;int y=Math.max(restoreY,scroll.getScrollY());restoreY=0;list.removeAllViews();boolean only=prefs.getBoolean("cached_only",false);String selected=OnlineMapSettings.prefs(this).getString("catalog","");int shown=0;
  for(String group:CatalogIndex.groups()){
   ArrayList<MapCatalog.Entry> entries=new ArrayList<>();for(MapCatalog.Entry e:CatalogIndex.entries(group)){long[] n=cache.get(e.key);if(!only||loading||(n!=null&&n[0]>0))entries.add(e);}if(entries.isEmpty())continue;shown+=entries.size();MapCatalog.Entry current=CatalogIndex.find(selected);boolean open=prefs.getBoolean("expanded_"+group,current!=null&&current.group.equals(group));
   LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.setPadding(dp(12),dp(10),dp(12),dp(10));heading.setMinimumHeight(dp(62));TextView arrow=label(open?"⬆":"⬇",24,0xff5d9365);heading.addView(arrow,new LinearLayout.LayoutParams(dp(36),dp(44)));LinearLayout names=new LinearLayout(this);names.setOrientation(1);TextView title=label(group.toUpperCase(Locale.ROOT),18,-1);names.addView(title);if(open){TextView copyright=label(entries.get(0).source.attribution,12,0xffd0d6c9);copyright.setMaxLines(2);names.addView(copyright);}heading.addView(names,new LinearLayout.LayoutParams(0,-2,1));heading.setContentDescription(group);heading.setOnClickListener(v->{prefs.edit().putBoolean("expanded_"+group,!open).commit();render();});list.addView(heading);View line=new View(this);line.setBackgroundColor(0xff3e4a36);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));
   if(open)for(MapCatalog.Entry e:entries)card(e,selected.equals(e.key));
  }
  if(shown==0){TextView empty=label("В кеше пока нет сохранённых карт",17,-1);empty.setPadding(dp(20),dp(24),dp(20),dp(24));list.addView(empty);}if(!loading)state.setText(only?"Показаны карты с сохранёнными тайлами":"54 источника · 3 набора · только локальные сведения о кеше");scroll.post(()->{if(!disposed)scroll.scrollTo(0,y);});
 }
 private void card(final MapCatalog.Entry e,boolean selected){
  FrameLayout card=new FrameLayout(this);LinearLayout.LayoutParams outer=new LinearLayout.LayoutParams(-1,dp(76));outer.setMargins(dp(12),dp(6),dp(12),dp(8));list.addView(card,outer);Bitmap bitmap=preview(CatalogIndex.preview(e.key));if(bitmap!=null){ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new FrameLayout.LayoutParams(-1,-1));}else card.setBackgroundColor(0xffe5e7d7);
  View veil=new View(this);veil.setBackgroundColor(0x65ffffff);card.addView(veil,new FrameLayout.LayoutParams(-1,-1));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(4),dp(2),dp(4));card.addView(row,new FrameLayout.LayoutParams(-1,-1));LinearLayout text=new LinearLayout(this);text.setOrientation(1);text.setGravity(Gravity.END);TextView title=label((selected?"✓ ":"")+e.source.name,19,0xff10170d);title.setGravity(Gravity.END);title.setMaxLines(2);text.addView(title);long[] n=cache.get(e.key);String cacheText=loading?"Кеш: проверка…":n==null?"Кеш: недоступен":n[0]==0?"Кеш: нет":String.format(Locale.US,"Кеш: %d тайлов · %.1f МиБ",n[0],n[1]/1048576.0);TextView detail=label(cacheText,12,0xff24381c);detail.setGravity(Gravity.END);text.addView(detail);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));text.setContentDescription(e.source.name);text.setOnClickListener(v->choose(e));card.setOnClickListener(v->choose(e));TextView more=icon("☰","Действия: "+e.source.name,()->actions(e));more.setTextColor(0xff536d77);row.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));
 }
 private Bitmap preview(String name){if(previews.containsKey(name))return previews.get(name);Bitmap b=null;try(InputStream in=getAssets().open("catalog-previews/"+name+".jpg")){b=BitmapFactory.decodeStream(in);}catch(IOException ignored){}previews.put(name,b);return b;}
 private void choose(MapCatalog.Entry e){OnlineMapSettings.select(this,e.key,project);setResult(RESULT_OK,new Intent().putExtra("catalog",e.key));finish();}
 private void returnAction(MapCatalog.Entry e,int action){if(e!=null)OnlineMapSettings.select(this,e.key,project);setResult(RESULT_OK,new Intent().putExtra(RESULT_ACTION,action));finish();}
 private void menu(){String[] choices={"Кеш и загрузка","Развернуть все группы","Свернуть все группы",prefs.getBoolean("cached_only",false)?"Показать все карты":"Показать только карты с кешем"};new AlertDialog.Builder(this).setTitle("Онлайн-карты").setItems(choices,(d,w)->{if(w==0)returnAction(null,ACTION_SETTINGS);else if(w==3){prefs.edit().putBoolean("cached_only",!prefs.getBoolean("cached_only",false)).commit();render();}else{SharedPreferences.Editor edit=prefs.edit();for(String g:CatalogIndex.groups())edit.putBoolean("expanded_"+g,w==1);edit.commit();render();}}).setNegativeButton("Закрыть",null).show();}
 private void actions(MapCatalog.Entry e){new AlertDialog.Builder(this).setTitle(e.source.name).setItems(new String[]{"Открыть карту","Кеш и загрузка","Экспорт кеша MBTiles","Сведения об источнике","Очистить кеш"},(d,w)->{if(w==0)choose(e);else if(w==1)returnAction(e,ACTION_SETTINGS);else if(w==2)returnAction(e,ACTION_EXPORT);else if(w==3)new AlertDialog.Builder(this).setTitle(e.source.name).setMessage(e.source.attribution+"\nМасштабы: "+e.source.minZoom+"–"+e.source.maxZoom+"\nСлоёв: "+e.source.leafs().length).setPositiveButton("Закрыть",null).show();else confirmClear(e);}).setNegativeButton("Закрыть",null).show();}
 private void confirmClear(MapCatalog.Entry e){new AlertDialog.Builder(this).setTitle("Очистить кеш?").setMessage("Удалить тайлы «"+e.source.name+"»? Общие слои используются и другими наборами. Объекты, вложения и импортированные карты сохранятся.").setPositiveButton("Очистить",(d,w)->{state.setText("Очистка кеша…");worker.execute(()->{String error=null;try{for(TileSource leaf:e.source.leafs()){if(disposed)return;try(OnlineTiles tiles=new OnlineTiles(this,leaf)){tiles.clear();}}}catch(Exception failure){error=failure.getMessage();}final String message=error;runOnUiThread(()->{if(disposed)return;if(message!=null)new AlertDialog.Builder(this).setMessage("Не удалось очистить кеш: "+message).setPositiveButton("Закрыть",null).show();scan();});});}).setNegativeButton("Отмена",null).show();}
 private void scan(){final int revision=++generation;loading=true;worker.execute(()->{Map<String,long[]> values=new HashMap<>(),leaves=new HashMap<>();for(MapCatalog.Entry e:MapCatalog.entries()){if(disposed)return;long[] total=new long[2];boolean valid=true;for(TileSource leaf:e.source.leafs()){long[] n;if(leaves.containsKey(leaf.id))n=leaves.get(leaf.id);else{n=readStats(leaf);leaves.put(leaf.id,n);}if(n==null){valid=false;break;}total[0]+=n[0];total[1]+=n[1];}values.put(e.key,valid?total:null);}runOnUiThread(()->{if(disposed||revision!=generation)return;cache.clear();cache.putAll(values);loading=false;render();});});}
 private long[] readStats(TileSource source){File file=new File(new File(getFilesDir(),"tile-cache"),source.id+".mbtiles");if(!file.exists())return new long[]{0,0};try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY);Cursor c=db.rawQuery("SELECT count(*),coalesce(sum(length(tile_data)),0) FROM tiles",null)){if(c.moveToFirst())return new long[]{c.getLong(0),c.getLong(1)};}catch(Exception ignored){}return null;}
 protected void onSaveInstanceState(Bundle out){out.putInt("scroll",scroll.getScrollY());super.onSaveInstanceState(out);}
 protected void onDestroy(){disposed=true;worker.shutdown();super.onDestroy();}
}
